-- Voorvertoning atlas: lichte gegevens voor de draft (198 zichtbare brouwers). De volledige gegevens met feiten en bronnen volgen via atlas-seed.sql.
INSERT INTO public.breweries (slug,name,municipality,province,lat,lng,brewery_category,type,established_year,visitable,has_own_installation,is_brewsite,atlas_visible,location_precision,first_seen)
SELECT t->>0,t->>1,t->>2,
 CASE t->>3 WHEN 'WV' THEN 'West-Vlaanderen' WHEN 'OV' THEN 'Oost-Vlaanderen' WHEN 'AN' THEN 'Antwerpen' WHEN 'VB' THEN 'Vlaams-Brabant' WHEN 'LI' THEN 'Limburg' WHEN 'BR' THEN 'Brussel' WHEN 'HE' THEN 'Henegouwen' WHEN 'WB' THEN 'Waals-Brabant' WHEN 'NA' THEN 'Namen' WHEN 'LU' THEN 'Luik' ELSE 'Luxemburg' END,
 (t->>4)::double precision,(t->>5)::double precision,
 CASE t->>6 WHEN 'p' THEN 'brewpub' WHEN 'f' THEN 'bierfirma' WHEN 'b' THEN 'blender' WHEN 'h' THEN 'hoevebrouwerij' ELSE 'microbrewery' END,
 CASE t->>6 WHEN 'f' THEN 'Contract brewer' WHEN 'b' THEN 'Blender/Stekerij' ELSE 'Microbrewery' END,
 (t->>7)::integer,
 CASE t->>8 WHEN 'j' THEN 'ja' WHEN 'a' THEN 'op afspraak' WHEN 'n' THEN 'nee' ELSE 'onbekend' END,
 CASE t->>9 WHEN '1' THEN true WHEN '0' THEN false ELSE NULL END,
 COALESCE(t->>9,'1')<>'0',true,'gemeente','2026-11-23'::date
