UPDATE public.breweries b SET facts_nl=t->>1, facts_en=t->>2, sources=t->3, flagship_beers=ARRAY(SELECT jsonb_array_elements_text(t->4)), website_url=COALESCE(b.website_url,t->>5), last_verified_at='2026-11-23T12:00:00Z'::timestamptz
FROM jsonb_array_elements($j$[
["de-straetebrouwerie","Eenmansbrouwerij van Brecht Verborgh in een tuinbrouwerij van 27 m² in Desselgem. Afhalen en bezoek gebeuren op afspraak.","One-man brewery run by Brecht Verborgh in a 27 m² garden brewery in Desselgem. Collection and visits are by appointment.",["https://www.straetebrouwerie.be","https://www.streekgenoot.be/bieren-van-lokale-brouwerijen-proeven/"],["Zwort"],"https://www.straetebrouwerie.be"],
["brouwerij-de-krak","Kleine brouwerij uit Zedelgem, als vennootschap opgericht in juni 2021 en op Untappd geregistreerd als nanobrouwerij. Stond in mei 2025 op het bierfestival van Koekelare.","Small brewery from Zedelgem, founded as a company in June 2021 and registered on Untappd as a nanobrewery. It was at the Koekelare beer festival in May 2025.",["https://www.brouwerijdekrak.com","https://busibee.be/en/0769359755-brouwerij-de-krak.md"],["Vice Versa","Alter Ego","Double Trouble"],"https://www.brouwerijdekrak.com"],
["brouwerij-angarde","Huisbrouwerij van drie brouwers, gestart tijdens de coronaperiode. De vaste bieren zijn genoemd naar middeleeuwse wapens en wapenrusting; sinds 2024 brouwt Angarde ook het Hippoliet-bier.","House brewery run by three brewers, started during the coronavirus period. The core beers are named after medieval weapons and armour; since 2024 Angarde has also brewed the Hippoliet beer.",["https://brouwerijangarde.be/","https://www.made-in.be/oost-vlaanderen/brouwerij-angarde-brouwt-voortaan-hippolietbier-in-eigen-dorp-de-cirkel-is-helemaal-rond/"],["Barbute","Arbalette","Hippoliet"],"https://brouwerijangarde.be/"],
["keun","Microbrouwerij van muzikant en auteur Gert Keunen aan de voet van de Muziekberg. Een bezoek met proeverij kan op afspraak en toont de brouwinstallatie en een klein hopveld.","Microbrewery run by musician and author Gert Keunen at the foot of the Muziekberg. A visit with a tasting is possible by appointment and takes in the brewing installation and a small hop field.",["https://www.ontdekronse.be/en/node/421","https://www.ontdekronse.be/en/node/264"],["KEUN Tripel Saison","KEUN Sterk Bruin","KEUN Spéciale Goud"],"https://www.keun.be"],
["brouwerij-varenbroek","Marc Knops uit Reet liet in 2015 een eigen brouwinstallatie bouwen voor brouwsels tot 25 hectoliter. Hij brouwt een eigen gamma en daarnaast bieren in opdracht van derden.","In 2015 Marc Knops from Reet had his own brewing installation built for brews of up to 25 hectolitres. He brews his own range and also beers commissioned by third parties.",["https://www.rumst.be/brouwerij-varenbroek","https://www.zythos.be/wp-content/uploads/2026/09/Lijst-van-brouwerijen-20260920.pdf"],["De Knots","REETro","Varenbroek Special"],null],
["huisbrouwerij-de-vliet","Jul Molenberghs brouwt sinds 1988 en maakt in Ten Aard bij Geel bieren naar een familierecept. Zijn kinderen en kleinkinderen werken mee.","Jul Molenberghs has been brewing since 1988 and makes beers to a family recipe in Ten Aard, near Geel. His children and grandchildren help out.",["https://www.huisbrouwerijdevliet.be","https://www.zythos.be/wp-content/uploads/2026/09/Lijst-van-brouwerijen-20260920.pdf"],["Vliet Dubbel","Vliet Tripel","Vliet Spelt"],"https://www.huisbrouwerijdevliet.be"],
["brouwerij-barak","In 2022 opgericht door Michaël Bynens, Jorn Vankrunkelsven en Bjorn Ruysen, die kleinschalig brouwen in ketels van 150 liter. De biernamen verwijzen naar het militaire kamp van Leopoldsburg.","Founded in 2022 by Michaël Bynens, Jorn Vankrunkelsven and Bjorn Ruysen, who brew on a small scale in 150-litre kettles. The beer names refer to the military camp of Leopoldsburg.",["https://www.3970leopoldsburg.be/en/we-have-a-brewery-again-in-leopoldsburg/","https://busibee.be/en/0782652517-brouwerij-barak"],["Marketentster Blond","Marketentster Tripel","Kampse Vlam"],"https://brouwerijbarak.be"],
["huisbrouwerij-de-geiteling","Kleinschalige huisbrouwerij in Wijchmaal die sinds 2018 brouwt en bieren in eigen kelders laat rijpen. De winkel is op zaterdag open, proeverijen en rondleidingen zijn op afspraak.","Small-scale house brewery in Wijchmaal that has been brewing since 2018 and matures beers in its own cellars. The shop is open on Saturdays; tastings and guided tours are by appointment.",["https://www.huisbrouwerijdegeiteling.be","https://www.zythos.be/wp-content/uploads/2026/09/Lijst-van-brouwerijen-20260920.pdf"],["Drie Zussen"],"https://www.huisbrouwerijdegeiteling.be"],
["geuzestekerij-odilon","Thomas Singelé, brandweerman in Halle, vulde in 2021 zijn eerste vaten in de voormalige brouwerij Jouret in Bever. Hij koopt wort aan, laat het rijpen op een zeventigtal eiken vaten en plande in 2025 een proeflokaal met café.","Thomas Singelé, a firefighter in Halle, filled his first barrels in 2021 in the former Jouret brewery in Bever. He buys in wort, matures it in around seventy oak barrels and in 2025 was planning a tasting room with a café.",["https://www.made-in.be/vlaams-brabant/brandweerman-thomas-trekt-naar-de-horeca-met-geuzestekerij-odilin-samen-geuze-proeven-dat-waren-de-gezelligste-familiemomenten/","https://lambic.info/Geuzestekerij_Odilon"],["Kriek Odilon","Framboise Odilon","Mirabel-Lambiek"],null],
["stekerij-ambreus","Vier geuzeliefhebbers die als hobby aangekochte lambiek versneden, besloten rond 2019 om er een project van te maken en vullen sinds 2020 vaten met wort van onder meer Den Herberg. De stekerij is open op de tweede zaterdag van de maand.","Four gueuze enthusiasts who blended bought-in lambic as a hobby decided around 2019 to turn it into a project, and since 2020 they have been filling barrels with wort from Den Herberg, among others. The gueuze blender is open on the second Saturday of the month.",["https://lambic.info/Stekerij_Ambreus","https://www.ambreus.be"],["Oude Geuze A L'Ancienne","Oude Kriek A L'Ancienne","Vlierbloesem Geuze"],"https://www.ambreus.be"],
["brasserie-113","Opgericht in december 2017 op de benedenverdieping van een oud huis in Bergen. Brouwt één dag per week, ongeveer 20 hectoliter per jaar, als bijberoep.","Founded in December 2017 on the ground floor of an old house in Mons. It brews one day a week, about 20 hectolitres a year, as a sideline.",["https://brasserie113.be","https://www.visitmons.be/en/producers/brasserie-113-177926"],["113 ambrée","113 blanche"],"https://brasserie113.be"],
["brasserie-blacksmith","In augustus 2019 gestart door twee vrienden en sinds 2021 in Waterloo gevestigd met een installatie van 200 liter in een oude familiesmidse. Biedt bezoeken, proeverijen en brouwworkshops aan.","Started in August 2019 by two friends and based in Waterloo since 2021, with a 200-litre installation in an old family forge. It offers visits, tastings and brewing workshops.",["https://blacksmith.odoo.com","https://www.destinationbw.be/en/fiche/local-producer/braserie-blacksmith-waterloo_TFOTER-A0-00S0-05IP/"],[],"https://blacksmith.odoo.com"],
["microbrasserie-des-3-chenes","Brouwerij in Pondrôme die haar cijfers publiceert: 9 brouwsels en 1.440 liter in 2024. Verkoop alleen na afspraak, geen proeverij ter plaatse.","Brewery in Pondrôme that publishes its figures: 9 brews and 1,440 litres in 2024. Sales are by appointment only and there are no tastings on site.",["https://troischenes.wixsite.com/microbrasserie","https://www.info-lux.com/microbrasserie-des-3-chenes-pondrome-beauraing/"],["Pondrôme IPA","Triple Déchenée","Stout 5574"],"https://troischenes.wixsite.com/microbrasserie"],
["brasserie-de-la-station","Kleine brouwerij uit 2020 die in ketels van 200 liter brouwt in een atelier naast de gezinswoning. De bieren zijn ongefilterd en ongepasteuriseerd en worden in Clavier gebotteld.","Small brewery from 2020 that brews in 200-litre kettles in a workshop next to the family home. The beers are unfiltered and unpasteurised and are bottled in Clavier.",["https://www.info-lux.com/brasserie-de-la-station-clavier/","https://brasseriedelastation.weebly.com/"],[],"https://brasseriedelastation.weebly.com/"]
]$j$::jsonb) AS t WHERE b.slug=t->>0;
